(OUT / 'tools-data.js').write_text('window.KENSEI_TOOLS=' + json.dumps({t[0]: {'name':t[2], 'description':t[4], 'category':t[5]} for t in TOOLS}, ensure_ascii=False) + ';', encoding='utf-8')
